}
fn _regex_replace(re: Regex, input: []const u8, sub: []const u8) []const u8 {
    var out: std.ArrayList(u8) = .empty;
    var i: usize = 0;
    while (i < input.len) {
        if (re.matchAt(input, i, re.flags.lazy_match) catch null) |e| {
