        const ms = @as(f64, @floatFromInt(e.total_ns)) / 1_000_000.0;
        const _s = std.fmt.allocPrint(std.heap.page_allocator, "  {s:<40}  {:>8}  {d:.3} ms\n", .{ e.key, e.calls, ms }) catch continue;
